def fizzbuzz(n):
    if n % 15 == 0:
        return 'FizzBuzz'
    if n % 3 == 0:
        return 'Fizz'
    if n % 5 == 0:
        return 'Buzz'
    return str(n)

def test_regular_number():
    assert fizzbuzz(1) == '1'
    assert fizzbuzz(7) == '7'

def test_fizz():
    assert fizzbuzz(3) == 'Fizz'
    assert fizzbuzz(6) == 'Fizz'

def test_buzz():
    assert fizzbuzz(5) == 'Buzz'
    assert fizzbuzz(10) == 'Buzz'

def test_fizzbuzz():
    assert fizzbuzz(15) == 'FizzBuzz'
    assert fizzbuzz(30) == 'FizzBuzz'

# Run all tests
for test in [test_regular_number, test_fizz, test_buzz, test_fizzbuzz]:
    test()
    print(f'{test.__name__} PASSED')
print('All TDD tests passed!')
